let cache_key = format!("v1::courses::page={page}::per={per_page}");

// line 110 — cache is only READ when page == 1
if page == 1 {
    if let Some(cached) = state.cache.get::<Paged<serde_json::Value>>(&cache_key).await? { ... }
}

// line 133 — cache is only WRITTEN when page == 1
